---
### Código Modificado para HeroController.cs

Aquí está el script actualizado para manejar los ataques básicos y el ataque de ráfaga:

```csharp
[SerializeField] private float normalAttackCooldown = 1.0f; // Enfriamiento del ataque básico normal
[SerializeField] private float quickAttackCooldown = 0.5f; // Enfriamiento de ataques consecutivos
[SerializeField] private float burstAttackCooldown = 3.0f; // Enfriamiento de la ráfaga
[SerializeField] private int attacksBeforeBurst = 5; // Número de básicos consecutivos antes de activar la ráfaga

private int attackCount = 0; // Conteo de ataques consecutivos
private bool isAttacking = false;
private bool isInBurstMode = false;
private float nextAttackTime = 0f;

// Llamada al ataque básico
public void ExecuteAttackBasic()
{
    if (isDead || Time.time < nextAttackTime) return;

    // Verifica si se activa la ráfaga
    if (attackCount >= attacksBeforeBurst)
    {
        TriggerBurstAttack();
        return;
    }

    // Dispara la animación según si es el ataque completo o recortado
    if (attackCount == 0)
    {
        PlayBasicAttackFull();
    }
    else
    {
        PlayBasicAttackQuick();
    }

    // Incrementa el contador de ataques consecutivos
    attackCount++;
    nextAttackTime = Time.time + (attackCount == 1 ? normalAttackCooldown : quickAttackCooldown);
    
    // Resetea el conteo si el jugador es demasiado lento
    StartCoroutine(ResetAttackCombo());
}

private void TriggerBurstAttack()
{
    if (isInBurstMode) return;

    if (anim != null)
    {
        anim.ResetTrigger("Attack");
        anim.SetTrigger("Burst");
    }

    Debug.Log($"{name} ¡Activó la ráfaga con ambas manos!");

    // Reinicia el contador y el cooldown para ataques
    isInBurstMode = true;
    attackCount = 0;
    nextAttackTime = Time.time + burstAttackCooldown;

    // Salir de modo ráfaga después de la animación
    StartCoroutine(ResetBurstMode());
}

private void PlayBasicAttackFull()
{
    if (anim != null)
    {
        anim.ResetTrigger("Attack");
        anim.SetTrigger("Attack"); // Usa la animación completa
    }

    Debug.Log($"{name} realiza un ataque completo con un arma.");
    AplicarDanoAlObjetivo(); // Aplica daño
}

private void PlayBasicAttackQuick()
{
    if (anim != null)
    {
        anim.ResetTrigger("Attack");
        anim.SetTrigger("Attack"); // Usa la animación recortada para fluidez
    }

    Debug.Log($"{name} realiza ataque consecutivo fluido con un arma.");
    AplicarDanoAlObjetivo(); // Aplica daño
}

private IEnumerator ResetAttackCombo()
{
    yield return new WaitForSeconds(1.5f); // Define el tiempo límite para continuar un combo
    attackCount = 0; // Si se supera este tiempo, se reinicia el contador
}

private IEnumerator ResetBurstMode()
{
    yield return new WaitForSeconds(1.0f); // Ajusta la duración de la ráfaga
    isInBurstMode = false;
}

private void AplicarDanoAlObjetivo()
{
    if (currentTarget == null) return;

    int danoFinal = Mathf.RoundToInt(attackDamage * porcentaje);

    // Detecta el tipo de objetivo y aplica lo correspondiente
    if (currentTarget.TryGetComponent(out Shard_Controller enemyShard))
    {
        enemyShard.TakeDamage(danoFinal);
        Debug.Log($"Impactó al shard: {enemyShard.name}");
    }
    else if (currentTarget.TryGetComponent(out HeroController enemyHero))
    {
        enemyHero.TakeDamage(danoFinal);
        Debug.Log($"Impactó al héroe: {enemyHero.name}");
    }
}
```

---

### Explicación del Código
1. **Ataque Básico Completo**:
   - El primer ataque siempre reproduce la animación completa mediante `PlayBasicAttackFull()`.
   - Tiene un cooldown más largo (`normalAttackCooldown`).

2. **Ataques Seguidos Recortados**:
   - Los ataques consecutivos (del segundo en adelante) reproducen una versión recortada de la animación con `PlayBasicAttackQuick()`.
   - Estos tienen un cooldown más corto (`quickAttackCooldown`) para ser más fluidos.

3. **Ataque de Ráfaga con Dos Armas**:
   - Al llegar al número definido de ataques consecutivos (`attacksBeforeBurst`), se activa el ataque de ráfaga mediante `TriggerBurstAttack()`.
   - Este disparará la animación de ráfaga (`Burst`) y reseteará el combo después de ejecutarlo.
   - Un temporizador (`burstAttackCooldown`) evita que el ataque de ráfaga sea spam.

4. **Reseteo del Combo**:
   - Si hay un tiempo muerto entre ataques consecutivos, el combo se resetea automáticamente con la rutina `ResetAttackCombo()`.

---

### Configuración del Animator
1. **Estados y Transiciones**:
   - `Idle → Attack` (condición: Trigger `Attack`).
   - `Attack → Attack` (para combos consecutivos, usa el mismo trigger con entrada fluida).
   - `Attack → Burst` (condición: Trigger `Burst`).
   - **Asegúrate de desmarcar `Has Exit Time` en las transiciones hacia `Burst` y combo fluido**.

2. **Clips de Animación**:
   - *Attack1_Full*: Usa la animación completa de disparo de un arma.
   - *Attack1_Quick*: Recorta la anticipación y/o recuperación del clip original usando el editor.
   - *Attack_Burst*: Usa la animación para el disparo de ráfaga.

---

